const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#173d36\"><meta name=\"description\" content=\"Wear a place that matters. Original coordinate-inspired t-shirts, personalized with your place, date and colors.\"><title>Somewhere Yours — Wear a place that matters</title>\n<style>\n:root{--cream:#f5f2e9;--green:#173d36;--lime:#d7ed9c;--ink:#213b34;--muted:#68746b;--line:#d5dacd;--serif:Georgia,'Times New Roman',serif}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0;background:var(--cream);color:var(--ink);font:15px/1.6 Arial,Helvetica,sans-serif}button,input,select{font:inherit}button,a,input,select{touch-action:manipulation}button,a{ -webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}button{cursor:pointer}button:disabled{cursor:wait;opacity:.6}:focus-visible{outline:3px solid #a77629;outline-offset:5px}.wrap{width:min(1280px,calc(100% - 100px));margin:auto}.nav{height:96px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;font-size:21px;letter-spacing:-1px;font-weight:700;line-height:1.05}.brand small{display:block;font-size:10px;letter-spacing:3px;font-weight:400;margin-top:6px}.mark{width:38px;height:38px;border:1px solid;border-radius:50%;position:relative;font-size:27px;line-height:36px;text-align:center}.navlinks{display:flex;gap:32px;align-items:center;font-size:13px}.nav .navcta{border:1px solid #a8b4a4;padding:11px 20px;border-radius:30px}.testbar{background:var(--green);color:#e8efda;text-align:center;font-size:11px;letter-spacing:.3px;padding:7px 18px}.hero{display:grid;grid-template-columns:1.02fr 1fr;min-height:690px;align-items:center;gap:45px;padding:46px 0 55px}.eyebrow{font-size:10px;letter-spacing:2.6px;text-transform:uppercase;font-weight:600}.eyebrow:before{content:'✳';margin-right:11px;font-size:16px}.hero h1{font:normal clamp(60px,6.9vw,104px)/.96 var(--serif);letter-spacing:-5px;margin:30px 0}.hero h1 em{font-weight:400;color:#798c69}.hero p{max-width:395px;font-size:16px;color:#5b695f;line-height:1.8;margin:26px 0}.btn{display:inline-flex;align-items:center;justify-content:center;gap:34px;border:0;background:var(--green);color:var(--cream);border-radius:4px;padding:17px 26px;font-size:14px}.btn:hover{background:#2c5348}.btn.light{background:var(--lime);color:var(--green)}.btn.outline{background:none;border:1px solid var(--line);color:var(--ink);gap:14px;padding:12px 18px}.hero-notes{display:flex;gap:23px;font-size:10px;margin-top:22px;color:var(--muted)}.hero-notes span:before{content:'✓';margin-right:6px}.hero-visual{background:#dce3d5;border-radius:130px 130px 8px 8px;position:relative;min-height:574px;display:grid;place-items:center;overflow:hidden}.hero-visual:before{content:'';width:360px;height:360px;border:1px solid #c2d0bc;border-radius:50%;position:absolute;left:50%;top:49%;transform:translate(-50%,-50%)}.stamp{position:absolute;right:20px;top:23px;width:87px;height:87px;border:1px solid var(--green);border-radius:50%;display:flex;flex-direction:column;justify-content:center;text-align:center;font-size:9px;letter-spacing:1.4px;transform:rotate(12deg);z-index:2;line-height:1.8}.stamp b{font:29px var(--serif)}.shirt{position:relative;width:98%;aspect-ratio:1/1.14;filter:drop-shadow(0 22px 17px #21342830);max-width:530px}.shirt svg{width:100%;height:100%;display:block}.shirt canvas{position:absolute;left:29.8%;top:27%;width:40.4%;height:auto;pointer-events:none;mix-blend-mode:normal}.hero-meta{position:absolute;bottom:23px;left:25px;right:25px;display:flex;justify-content:space-between;border-top:1px solid #b6c4b0;padding-top:13px;font-size:9px;letter-spacing:1.5px}.hero-meta b{font-size:11px}.ticker{border-top:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;justify-content:space-between;padding:20px 0;font-size:11px;letter-spacing:1.7px}.ticker i{font-style:normal;color:#799461}.intro{display:flex;justify-content:space-between;align-items:end;padding:80px 0 34px;gap:25px}h2{font:normal 45px/1.12 var(--serif);letter-spacing:-1.7px;margin:12px 0} .intro p{color:var(--muted);max-width:340px;font-size:14px}.examples{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.example{border:0;background:none;text-align:left;color:var(--ink);padding:0}.example-art{display:flex;align-items:center;justify-content:center;background:#e2e7db;border-radius:5px;min-height:310px;overflow:hidden;transition:transform .2s}.example:hover .example-art{transform:translateY(-5px)}.example-art.peach{background:#ead9ca}.example-art.blue{background:#dce2e5}.example .shirt{width:80%;margin:-5px 0 -12px}.example-meta{display:flex;justify-content:space-between;align-items:center;margin-top:15px}.example-meta b{font-size:14px;font-weight:500}.example-meta small{color:var(--muted);display:block;font-size:10px;letter-spacing:.6px;margin-top:3px}.example-meta span{font-size:22px}.examples-note{font-size:11px;color:var(--muted);margin-top:20px}.studio{margin-top:85px;padding:65px 0;border-top:1px solid var(--line)}.studio-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:28px}.studio-head span{font-size:12px}.studio-grid{display:grid;grid-template-columns:1.05fr 1fr;gap:65px}.preview-panel{position:sticky;top:20px;align-self:start;background:#e0e5d9;border-radius:5px;overflow:hidden;padding:20px 20px 22px;display:grid;justify-items:center;min-height:570px}.preview-panel .shirt{width:100%;margin-top:-10px}.preview-label{display:flex;justify-content:space-between;width:100%;font-size:9px;letter-spacing:1.8px;text-transform:uppercase}.preview-footer{display:flex;justify-content:space-between;align-items:center;width:100%;border-top:1px solid #bcc9b5;padding-top:14px}.preview-footer p{font-size:11px;margin:0;color:#5f705e}.text-button{border:0;background:none;color:inherit;text-decoration:underline;font-size:11px;padding:8px}.step{border:0;padding:0;margin:0 0 28px;min-width:0}.step legend{padding:0;margin-bottom:15px;font-size:13px;font-weight:600}.step legend span{display:inline-block;border:1px solid #b6c1aa;border-radius:50%;font:10px/24px Arial;width:25px;text-align:center;margin-right:10px}label{display:block;font-size:11px;margin-bottom:6px;color:#5b695f}.field{margin-bottom:15px}.input{background:#fbfaf6;border:1px solid #cfd5c7;border-radius:4px;padding:12px 13px;color:var(--ink);width:100%;min-width:0;outline-offset:0}input.input:focus{border-color:var(--green)}.row{display:grid;grid-template-columns:1fr 1fr;gap:13px}.help{font-size:10px;line-height:1.6;color:var(--muted);margin:7px 0}.palette-options,.color-options,.sizes{display:flex;gap:8px;flex-wrap:wrap}.palette-option{flex:1;border:1px solid #cfd5c7;background:#faf9f2;border-radius:4px;padding:11px 10px;display:flex;align-items:center;gap:8px;font-size:11px;color:var(--ink)}.palette-option[aria-pressed=true],.swatch[aria-pressed=true],.size[aria-pressed=true]{border-color:var(--green);box-shadow:0 0 0 1px var(--green)}.dots{display:flex}.dots i{display:block;width:14px;height:14px;border-radius:50%;border:1px solid #0001}.dots i+ i{margin-left:-4px}.swatch{border:1px solid #cfd5c7;background:#fbfaf6;border-radius:4px;display:flex;gap:9px;align-items:center;font-size:11px;padding:10px 13px;color:var(--ink)}.swatch i{width:15px;height:15px;border-radius:50%;border:1px solid #aaa}.size{min-width:46px;border:1px solid #cfd5c7;background:#fbfaf6;border-radius:4px;padding:10px;color:var(--ink);font-size:12px}.size[aria-pressed=true]{background:var(--green);color:var(--cream)}.size-header{display:flex;align-items:center;justify-content:space-between;margin:18px 0 8px}.size-header label{margin:0}.checkout-box{border-top:1px solid var(--line);padding-top:20px}.price-row{display:flex;justify-content:space-between;margin-bottom:7px;font-size:12px}.price-row.total{font-size:16px;font-weight:600;margin:12px 0 17px}.checkout-box .btn{width:100%;justify-content:space-between}.consent{display:flex;align-items:start;gap:8px;font-size:11px;color:#5d6b5f;margin:16px 0}.consent input{margin-top:4px;accent-color:var(--green)}.notice{font-size:11px;border:1px solid #d6c8a9;background:#f0e8d5;color:#685b3d;padding:12px;border-radius:4px;margin:13px 0}.error{color:#8c382e;font-size:12px;min-height:20px;margin-top:10px}.fineprint{font-size:10px;color:var(--muted);text-align:center;margin:12px 0 0}.story{background:var(--green);color:var(--cream);margin-top:20px;border-radius:6px;padding:55px;display:grid;grid-template-columns:1.1fr 1fr;gap:65px}.story h2{font-size:45px;margin:15px 0 22px}.story p{font-size:14px;line-height:1.8;color:#ccd5c4;max-width:450px}.story-steps{display:grid;gap:26px}.story-step{display:flex;gap:20px;border-bottom:1px solid #ffffff25;padding-bottom:20px}.story-step:last-child{border:0}.story-step span{font:30px var(--serif);color:var(--lime)}.story-step b{font-weight:500;font-size:16px}.story-step p{font-size:12px;margin:5px 0 0;max-width:320px}.faq{display:grid;grid-template-columns:.7fr 1fr;gap:65px;padding:90px 0}.faq h2{max-width:260px}.faq details{border-bottom:1px solid var(--line);padding:18px 0}.faq summary{cursor:pointer;list-style:none;font-size:14px;display:flex;justify-content:space-between}.faq summary:after{content:'+';font-size:19px}.faq details[open] summary:after{content:'−'}.faq details p{font-size:13px;color:var(--muted);line-height:1.8;max-width:530px}.footer{border-top:1px solid var(--line);padding:30px 0 42px;display:flex;align-items:center;justify-content:space-between;font-size:10px;color:var(--muted)}.footer-links{display:flex;gap:22px}.footer button{background:none;border:0;font-size:10px;color:inherit;padding:0}dialog{background:var(--cream);color:var(--ink);border:1px solid var(--line);border-radius:8px;max-width:600px;width:calc(100% - 40px);padding:35px;max-height:85vh}dialog::backdrop{background:#10271e80}dialog .close{float:right;border:0;background:none;font-size:25px;color:inherit}dialog h2{font-size:30px}dialog p,dialog li{font-size:13px;color:var(--muted)}table{border-collapse:collapse;width:100%;font-size:13px;margin:20px 0}td,th{text-align:left;border-bottom:1px solid var(--line);padding:9px}.order-view{min-height:65vh;padding:65px 0;max-width:700px;margin:auto}.order-view h1{font:55px/1.08 var(--serif);letter-spacing:-2px;margin:20px 0}.order-card{padding:27px;border:1px solid var(--line);border-radius:5px;background:#fbfaf6;margin:25px 0}.order-card p{margin:8px 0;font-size:13px}.order-ref{font-family:monospace;font-size:11px;overflow-wrap:anywhere}.order-status{display:inline-block;padding:6px 12px;background:#dce9c9;border-radius:20px;font-size:11px}.hidden{display:none!important}@media(max-width:1000px){.wrap{width:calc(100% - 50px)}.hero{gap:20px;min-height:580px}.hero h1{font-size:75px}.hero-visual{min-height:480px}.studio-grid{gap:30px}.preview-panel{min-height:440px}.palette-option{gap:6px;padding:9px 6px;font-size:10px}.story{gap:35px;padding:38px}.hero-notes{gap:10px}.example-art{min-height:250px}}@media(max-width:720px){.wrap{width:calc(100% - 36px)}.nav{height:77px}.brand{font-size:18px}.mark{width:32px;height:32px;line-height:30px;font-size:23px}.navlinks{gap:15px}.navlinks .navhow{display:none}.nav .navcta{font-size:11px;padding:8px 13px}.testbar{font-size:10px}.hero{display:flex;flex-direction:column;align-items:stretch;padding:43px 0 35px;gap:35px}.hero h1{font-size:77px;letter-spacing:-3.5px;margin:22px 0}.hero p{font-size:14px;margin:20px 0;max-width:350px}.hero-visual{min-height:480px;max-width:520px;width:100%;align-self:center;border-radius:110px 110px 5px 5px}.hero-notes{gap:22px}.hero-meta{font-size:8px}.hero-meta b{font-size:10px}.ticker{gap:15px;font-size:8px;letter-spacing:1px;padding:17px 0}.ticker span:nth-of-type(3){display:none}.intro{padding-top:52px;display:block}h2{font-size:36px}.intro p{font-size:12px;margin-top:15px;max-width:340px}.examples{grid-template-columns:1fr;gap:25px}.example-art{min-height:300px;max-height:390px}.example .shirt{max-width:350px}.examples-note{font-size:10px}.studio{margin-top:48px;padding:42px 0}.studio-grid{grid-template-columns:1fr;gap:30px}.preview-panel{position:static;min-height:430px;max-height:610px;padding:18px}.preview-panel .shirt{max-width:450px}.studio-head span{font-size:10px}.palette-option{font-size:11px;padding:12px 8px}.story{padding:30px 25px;grid-template-columns:1fr;gap:28px;margin-top:5px}.story h2{font-size:35px}.story p{font-size:12px}.faq{grid-template-columns:1fr;gap:10px;padding:54px 0}.faq h2{max-width:none}.footer{align-items:start;gap:25px;flex-direction:column}.footer-links{flex-wrap:wrap;gap:18px}.order-view{padding:40px 0}.order-view h1{font-size:43px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}\n</style><script defer src=\"/app.js?v=5\"></script></head>\n<body><div class=\"testbar\" id=\"testbar\">SANDBOX STORE · Personalize freely. Test orders won’t be charged or shipped.</div>\n<header class=\"wrap nav\"><a class=\"brand\" href=\"/\" aria-label=\"Somewhere Yours home\"><span class=\"mark\" aria-hidden=\"true\">✳</span><span>somewhere yours<small>WEAR A PLACE THAT MATTERS</small></span></a><nav class=\"navlinks\"><a class=\"navhow\" href=\"/#how\">The idea</a><a class=\"navcta\" href=\"/#studio\">Create your shirt ↗</a></nav></header>\n<main id=\"storefront\">\n<section class=\"wrap hero\"><div><div class=\"eyebrow\">Your story. Your coordinates.</div><h1>You had to<br><em>be there.</em></h1><p>That first trip. Your favorite escape. The place you call home. Turn somewhere special into a shirt that’s entirely yours.</p><a href=\"#studio\" class=\"btn\">Make it yours <span>↗</span></a><div class=\"hero-notes\"><span>Made just for you</span><span>From $36</span><span>No minimums</span></div></div><div class=\"hero-visual\"><div class=\"stamp\">ONE PLACE<b>1 / 1</b>ONE OF ONE</div><div class=\"shirt\" id=\"hero-shirt\"></div><div class=\"hero-meta\"><div>FIELD NOTES / 001<br><b>BIG SUR, CALIFORNIA</b></div><div>36.2704° N<br>121.8081° W</div></div></div></section>\n<div class=\"wrap ticker\"><span>PERSONAL BY DESIGN</span><i>✳</i><span>PRINTED ON DEMAND</span><i>✳</i><span>YOUR OWN COORDINATES</span><i>✳</i><span>SMALL STORIES. BIG MEANING.</span></div>\n<section class=\"wrap\" aria-labelledby=\"collection-title\"><div class=\"intro\"><div><div class=\"eyebrow\">A little inspiration</div><h2 id=\"collection-title\">Every place has a person.</h2></div><p>Three starting points. Endless personal stories.<br>Choose a mood, then make the details your own.</p></div><div class=\"examples\"><button class=\"example\" data-preset=\"big-sur\"><div class=\"example-art\"><div class=\"shirt\" id=\"example-0\"></div></div><div class=\"example-meta\"><div><b>The great escape</b><small>BIG SUR / TIDE / BLACK</small></div><span>↗</span></div></button><button class=\"example\" data-preset=\"joshua-tree\"><div class=\"example-art peach\"><div class=\"shirt\" id=\"example-1\"></div></div><div class=\"example-meta\"><div><b>The golden hour</b><small>JOSHUA TREE / EMBER / NATURAL</small></div><span>↗</span></div></button><button class=\"example\" data-preset=\"new-york\"><div class=\"example-art blue\"><div class=\"shirt\" id=\"example-2\"></div></div><div class=\"example-meta\"><div><b>The place called home</b><small>NEW YORK / BLUE / WHITE</small></div><span>↗</span></div></button></div><p class=\"examples-note\">Illustrative designs. Each print is original generative art inspired by your coordinates, rather than a geographic map.</p></section>\n<section class=\"wrap studio\" id=\"studio\" aria-labelledby=\"studio-title\"><div class=\"studio-head\"><div><div class=\"eyebrow\">The personal print studio</div><h2 id=\"studio-title\">Put your place on it.</h2></div><span>ONE SHIRT. ALL YOU.</span></div><div class=\"studio-grid\"><div class=\"preview-panel\"><div class=\"preview-label\"><span>Live front preview</span><span id=\"preview-color\">Black / Tide</span></div><div class=\"shirt\" id=\"studio-shirt\"></div><div class=\"preview-footer\"><p>Gildan Softstyle · Unisex<br>Original artwork, printed just for you</p><button class=\"text-button\" id=\"download\" type=\"button\">Download print PNG ↓</button></div><p class=\"help\">Digital mockup. Print placement and colors may vary on fabric.</p></div>\n<form id=\"design-form\"><fieldset class=\"step\"><legend><span>01</span>A place that means something</legend><div class=\"field\"><label for=\"place\">Place name · printed on your shirt</label><input class=\"input\" id=\"place\" name=\"place\" value=\"BIG SUR\" maxlength=\"22\" pattern=\"[\\x20-\\x7E]+\" required autocomplete=\"off\"><p class=\"help\">Up to 22 characters. Use Latin letters, numbers, or punctuation.</p></div><div class=\"row\"><div class=\"field\"><label for=\"lat\">Latitude</label><input class=\"input\" id=\"lat\" name=\"lat\" type=\"number\" step=\"0.0001\" min=\"-90\" max=\"90\" value=\"36.2704\" required></div><div class=\"field\"><label for=\"lon\">Longitude</label><input class=\"input\" id=\"lon\" name=\"lon\" type=\"number\" step=\"0.0001\" min=\"-180\" max=\"180\" value=\"-121.8081\" required></div></div><p class=\"help\">Use coordinates from your map app. They shape your own abstract landscape.<br>Positive = north / east. Negative = south / west.</p><div class=\"row\"><div class=\"field\"><label for=\"date\">A date to remember</label><input class=\"input\" id=\"date\" name=\"date\" type=\"date\" min=\"1900-01-01\" max=\"2100-12-31\" value=\"2024-08-17\" required></div><div class=\"field\"><label for=\"caption\">Your small story</label><input class=\"input\" id=\"caption\" name=\"caption\" value=\"WHERE I FEEL MOST ALIVE\" maxlength=\"32\" pattern=\"[\\x20-\\x7E]+\" required></div></div></fieldset>\n<fieldset class=\"step\"><legend><span>02</span>Find your color story</legend><div class=\"palette-options\" role=\"group\" aria-label=\"Print palette\"><button type=\"button\" class=\"palette-option\" data-palette=\"tide\" aria-pressed=\"true\"><span class=\"dots\"><i style=\"background:#edaa82\"></i><i style=\"background:#8da994\"></i></span>Tide</button><button type=\"button\" class=\"palette-option\" data-palette=\"ember\" aria-pressed=\"false\"><span class=\"dots\"><i style=\"background:#c76536\"></i><i style=\"background:#dab263\"></i></span>Ember</button><button type=\"button\" class=\"palette-option\" data-palette=\"blue\" aria-pressed=\"false\"><span class=\"dots\"><i style=\"background:#3855a6\"></i><i style=\"background:#7296ab\"></i></span>Blue</button></div></fieldset>\n<fieldset class=\"step\"><legend><span>03</span>Your shirt, your fit</legend><label>Shirt color</label><div class=\"color-options\" role=\"group\" aria-label=\"Shirt color\"><button type=\"button\" class=\"swatch\" data-color=\"black\" aria-pressed=\"true\"><i style=\"background:#252726\"></i>Black</button><button type=\"button\" class=\"swatch\" data-color=\"natural\" aria-pressed=\"false\"><i style=\"background:#e8ddbc\"></i>Natural</button><button type=\"button\" class=\"swatch\" data-color=\"white\" aria-pressed=\"false\"><i style=\"background:#fff\"></i>White</button></div><div class=\"size-header\"><label>Unisex size</label><button class=\"text-button\" data-dialog=\"size-guide\" type=\"button\">Size guide ↗</button></div><div class=\"sizes\" role=\"group\" aria-label=\"Shirt size\"><button type=\"button\" class=\"size\" data-size=\"s\" aria-pressed=\"false\">S</button><button type=\"button\" class=\"size\" data-size=\"m\" aria-pressed=\"true\">M</button><button type=\"button\" class=\"size\" data-size=\"l\" aria-pressed=\"false\">L</button><button type=\"button\" class=\"size\" data-size=\"xl\" aria-pressed=\"false\">XL</button><button type=\"button\" class=\"size\" data-size=\"2xl\" aria-pressed=\"false\">2XL</button></div><p class=\"help\">Soft ring-spun cotton · Semi-fitted crew neck · US shipping</p></fieldset>\n<div class=\"checkout-box\"><div class=\"price-row\"><span>Your personalized shirt</span><span>$36.00</span></div><div class=\"price-row\"><span>Standard US shipping</span><span>$5.00</span></div><div class=\"price-row total\"><span>Total before tax</span><span>$41.00</span></div><label class=\"consent\"><input type=\"checkbox\" id=\"approve\" required><span>I’ve checked my place, coordinates, date, and size. This is the design I want printed.</span></label><button class=\"btn\" type=\"submit\" id=\"checkout-button\"><span>Continue to checkout</span><span>↗</span></button><div class=\"notice\" id=\"payment-notice\">Connecting to the checkout service…</div><p class=\"error\" id=\"checkout-error\" role=\"alert\"></p><p class=\"fineprint\">Secure payment with Stripe · Printed after payment succeeds</p></div></form></div></section>\n<section class=\"wrap story\" id=\"how\"><div><div class=\"eyebrow\">More than a souvenir</div><h2>Some places<br>stay with you.</h2><p>We make shirts for the memories you can’t pin to a fridge. A favorite coastline. The street where you met. A hometown you carry everywhere.</p><p>Your coordinates shape a unique landscape; your words make it personal. Full-color DTG printing turns that one-off artwork into something you can wear.</p></div><div class=\"story-steps\"><div class=\"story-step\"><span>01</span><div><b>Tell us where.</b><p>Choose your place, its coordinates, a date and a little line that says what it means.</p></div></div><div class=\"story-step\"><span>02</span><div><b>Make it feel like you.</b><p>Pick your palette, shirt and size. See your design update as you make it.</p></div></div><div class=\"story-step\"><span>03</span><div><b>We take it from here.</b><p>After a successful payment, Prodigi prints your approved artwork and ships your shirt.</p></div></div></div></section>\n<section class=\"wrap faq\" aria-labelledby=\"faq-title\"><div><div class=\"eyebrow\">A few field notes</div><h2 id=\"faq-title\">Good things<br>to know.</h2></div><div><details><summary>Is the landscape a map of my location?</summary><p>It’s an original abstract landscape inspired by your coordinates, place name and date. The coordinates are printed exactly as you enter them, but the contours are artistic and don’t represent actual terrain. Check your location in your map app before approving.</p></details><details><summary>What shirt will I receive?</summary><p>A Gildan 64000 Softstyle unisex tee, with your customized design printed on the front using direct-to-garment technology. Black, natural and white are available in S–2XL. These solid colors are cotton. The digital shirt illustration is a preview; order a physical sample before relying on exact placement or colors.</p></details><details><summary>How long does delivery take?</summary><p>The store currently runs in sandbox mode, so test orders aren’t physically printed or shipped. For live orders, production and transit vary by facility and destination. Shipping estimates must be confirmed before the production launch. This store currently accepts US addresses only.</p></details><details><summary>Can I change or return a personalized shirt?</summary><p>Check every detail before paying: each shirt is made to your approved design. Production can start quickly after payment. For damaged, incorrect or defective items, save your order reference and photos. The merchant must publish a support address and final returns policy before accepting live orders.</p></details><details><summary>How do I care for a DTG print?</summary><p>Wash inside out with like colors on a cool, gentle cycle. Use mild detergent; avoid bleach and ironing directly over the print. Air drying helps preserve the artwork.</p></details></div></section>\n</main>\n<main id=\"order-view\" class=\"wrap order-view hidden\" aria-live=\"polite\"><div class=\"eyebrow\">Your personal field print</div><h1 id=\"order-title\">Checking your order…</h1><p id=\"order-message\">We’re confirming payment with Stripe.</p><div class=\"order-card\" id=\"order-card\"></div><p class=\"error\" id=\"order-error\" role=\"alert\"></p><button class=\"btn outline\" id=\"refresh-order\">Refresh order status ↻</button><a class=\"btn\" href=\"/#studio\">Back to the studio ↗</a><p class=\"help\">Keep this page’s full link to revisit your order. It contains your private access token.</p></main>\n<footer class=\"wrap footer\"><div>✳ SOMEWHERE YOURS<br>A small tribute to your somewhere.</div><div class=\"footer-links\"><button data-dialog=\"privacy\">Privacy</button><button data-dialog=\"terms\">Store terms</button><a href=\"/#studio\">Make something personal ↗</a><span>© 2026 Somewhere Yours</span></div></footer>\n<dialog id=\"size-guide\"><button class=\"close\" aria-label=\"Close dialog\">×</button><div class=\"eyebrow\">Gildan 64000 · Unisex</div><h2>Find your fit.</h2><p>Semi-fitted cut. Compare your chest circumference with the manufacturer’s chest-to-fit measurements below. If you prefer a relaxed fit, consider sizing up.</p><table><thead><tr><th>Size</th><th>Chest to fit</th></tr></thead><tbody><tr><td>S</td><td>34–36 in</td></tr><tr><td>M</td><td>38–40 in</td></tr><tr><td>L</td><td>42–44 in</td></tr><tr><td>XL</td><td>46–48 in</td></tr><tr><td>2XL</td><td>50–52 in</td></tr></tbody></table><p>Measurements are guidance, not a garment measurement guarantee. Confirm fit with a sample before production.</p></dialog>\n<dialog id=\"privacy\"><button class=\"close\" aria-label=\"Close dialog\">×</button><h2>Your story stays yours.</h2><p>Design preferences may be saved on this device. When you check out, we store your approved design, print file and order reference. Stripe handles card information; this store never receives full card details.</p><p>After payment succeeds, shipping details and your artwork are shared with Prodigi to fulfill the order. Your artwork has an unlisted download URL that Prodigi needs to access. Anyone with that URL can view it. Avoid putting sensitive personal information in your print.</p><p>Order links contain a private token; keep them private. This sandbox preview has no advertising trackers. Merchant contact information, data-retention rules and a final privacy policy are required before accepting live sales.</p></dialog>\n<dialog id=\"terms\"><button class=\"close\" aria-label=\"Close dialog\">×</button><h2>Sandbox store terms.</h2><p>This is a public test store. Stripe test payments use test card numbers and do not charge real money. Prodigi sandbox orders do not print or ship shirts. Checkout becomes available after the merchant connects Stripe.</p><p>A customized tee is $36 plus $5 standard US shipping, before applicable tax. You approve the print and selected shirt before checkout. Colors and placement in the illustration are approximate.</p><p>Production launch requires merchant identity and support contact, verified shipping estimates, tax configuration, and final privacy and returns terms. This store is not accepting live sales yet.</p></dialog>\n</body></html>\n";
const APP = "'use strict';\nconst $=selector=>document.querySelector(selector);\nconst $$=selector=>Array.from(document.querySelectorAll(selector));\nconst presets={\n 'big-sur':{place:'BIG SUR',caption:'WHERE I FEEL MOST ALIVE',lat:36.2704,lon:-121.8081,date:'2024-08-17',color:'black',size:'m',palette:'tide'},\n 'joshua-tree':{place:'JOSHUA TREE',caption:'THE DAYS WE GOT LOST',lat:34.1347,lon:-116.3131,date:'2025-04-12',color:'natural',size:'m',palette:'ember'},\n 'new-york':{place:'NEW YORK',caption:'THERE IS NO PLACE LIKE HOME',lat:40.7128,lon:-74.006,date:'2023-09-02',color:'white',size:'m',palette:'blue'}\n};\nconst palettes={tide:['#edaa82','#8da994','#b4c5a0'],ember:['#c76536','#b08842','#d7a551'],blue:['#3855a6','#63899b','#8db9c2']};\nlet state={...presets['big-sur']},configuration=null,requestId=crypto.randomUUID();\nfunction coords(d){return Math.abs(d.lat).toFixed(4)+'° '+(d.lat<0?'S':'N')+' / '+Math.abs(d.lon).toFixed(4)+'° '+(d.lon<0?'W':'E');}\nfunction hash(text){let n=2166136261;for(let i=0;i<text.length;i++){n^=text.charCodeAt(i);n=Math.imul(n,16777619);}return (n>>>0)/4294967295;}\nfunction drawDesign(canvas,d,w=1000,h=1257){\n canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.scale(w/1000,h/1257);ctx.clearRect(0,0,1000,1257);\n const p=[...palettes[d.palette]],ink=d.color==='black'?'#ede8d9':'#273e36';\n if(d.color!=='black'){const tones={tide:['#426858','#66834e'],ember:['#8d693c','#a77a34'],blue:['#446b80','#4d818b']}[d.palette];p[1]=tones[0];p[2]=tones[1];}\n const seed=hash(d.place+'|'+d.lat+'|'+d.lon+'|'+d.date),phase=seed*Math.PI*2;\n function text(value,y,size,font='Georgia',color=ink){ctx.fillStyle=color;ctx.textAlign='center';ctx.font=(font==='Arial'?'500 ':'')+size+'px '+font;ctx.fillText(value,500,y,800);}\n ctx.strokeStyle=ink;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(120,133);ctx.lineTo(880,133);ctx.stroke();\n text('S O M E W H E R E   Y O U R S',110,17,'Arial');\n const title=d.place.toUpperCase();ctx.font='77px Georgia';const titleWidth=ctx.measureText(title).width;text(title,235,Math.min(77,77*780/Math.max(1,titleWidth)));\n const cx=500,cy=580,r=310;\n ctx.save();ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.clip();\n // A full-color sunset and fine contour lines with plenty of garment showing through.\n const sunX=500+Math.sin(phase)*76,sunY=446+Math.cos(phase)*23;\n ctx.fillStyle=p[0];ctx.beginPath();ctx.arc(sunX,sunY,110+seed*18,0,Math.PI*2);ctx.fill();\n for(let i=0;i<7;i++){ctx.clearRect(190,sunY+30+i*13,620,3+i*.3);}\n ctx.fillStyle=ink;ctx.globalAlpha=.55;\n for(let i=0;i<24;i++){const a=i*2.39996+phase;const rr=125+(i*19)%180;ctx.beginPath();ctx.arc(500+Math.cos(a)*rr,480+Math.sin(a)*rr*.62,1.8,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;\n for(let i=0;i<34;i++){\n  ctx.beginPath();ctx.strokeStyle=i<18?p[1]:p[2];ctx.lineWidth=i%6===0?4:2.7;\n  for(let x=180;x<=820;x+=4){const nx=(x-500)/320;const y=565+i*11+Math.sin(nx*3.5+phase+i*.027)*35+Math.cos(nx*6.3-phase)*17+(Math.sin(nx*1.9+phase)*17)*(i/34);if(x===180)ctx.moveTo(x,y);else ctx.lineTo(x,y);}\n  ctx.stroke();\n }\n ctx.restore();\n ctx.strokeStyle=ink;ctx.lineWidth=2;ctx.beginPath();ctx.arc(cx,cy,r+13,-Math.PI*.89,-Math.PI*.13);ctx.stroke();\n // Compass crosshair and an individual field-print index.\n ctx.strokeStyle=ink;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(490,585);ctx.lineTo(510,585);ctx.moveTo(500,575);ctx.lineTo(500,595);ctx.stroke();\n text(coords(d),966,23,'Arial');\n text(d.caption.toUpperCase(),1026,28,'Arial');\n const parsed=new Date(d.date+'T12:00:00Z');const date=isNaN(parsed.getTime())?d.date:parsed.toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric',timeZone:'UTC'}).toUpperCase();\n text(date+'   ·   FIELD PRINT '+String(Math.floor(seed*9999)).padStart(4,'0'),1080,19,'Arial');\n ctx.beginPath();ctx.moveTo(120,1123);ctx.lineTo(880,1123);ctx.stroke();text('A   P L A C E   T O   K E E P',1161,15,'Arial');\n return canvas;\n}\nfunction shirt(container,d){\n const color={black:'#242826',natural:'#e8ddbd',white:'#f6f5ef'}[d.color],shade={black:'#121715',natural:'#beb395',white:'#d5d5cd'}[d.color];\n const key=container.id.replace(/[^a-z0-9]/g,'');\n container.innerHTML='<svg viewBox=\"0 0 600 684\" aria-hidden=\"true\"><defs><linearGradient id=\"fabric'+key+'\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\".1\"><stop stop-color=\"'+shade+'\"/><stop offset=\".2\" stop-color=\"'+color+'\"/><stop offset=\".52\" stop-color=\"'+color+'\"/><stop offset=\"1\" stop-color=\"'+shade+'\"/></linearGradient><linearGradient id=\"neck'+key+'\" x2=\"0\" y2=\"1\"><stop stop-color=\"'+shade+'\"/><stop offset=\"1\" stop-color=\"'+color+'\"/></linearGradient></defs><path d=\"M206 100 L239 85 Q300 104 361 85 L394 100 L500 157 L547 267 L459 304 L424 244 L426 570 Q300 589 174 570 L176 244 L141 304 L53 267 L100 157 Z\" fill=\"url(#fabric'+key+')\"/><path d=\"M239 85 Q300 145 361 85 Q351 154 300 155 Q249 154 239 85\" fill=\"'+shade+'\"/><path d=\"M248 93 Q300 121 352 93 Q343 144 300 144 Q257 144 248 93\" fill=\"url(#neck'+key+')\"/><path d=\"M208 105 Q178 160 177 244 M392 105 Q422 160 423 244 M60 261 L143 295 M540 261 L457 295 M176 561 Q300 579 424 561\" fill=\"none\" stroke=\"'+shade+'\" stroke-width=\"2\" opacity=\".6\"/><path d=\"M187 286 Q181 421 186 535 M413 284 Q418 415 411 542\" fill=\"none\" stroke=\"'+shade+'\" stroke-width=\"3\" opacity=\".32\"/><path d=\"M238 150 Q224 176 225 200 M362 150 Q375 180 374 200\" fill=\"none\" stroke=\"'+shade+'\" stroke-width=\"2\" opacity=\".3\"/></svg><canvas role=\"img\" aria-label=\"Personalized '+d.place.replace(/[<>\"']/g,'')+' shirt design\"></canvas>';\n drawDesign(container.querySelector('canvas'),d,1000,1257);\n}\nfunction render(){\n shirt($('#studio-shirt'),state);$('#preview-color').textContent=state.color+' / '+state.palette;\n for(const key of ['palette','color','size'])for(const b of $$('[data-'+key+']'))b.setAttribute('aria-pressed',String(b.dataset[key]===state[key]));\n try{localStorage.setItem('somewhere-yours-design',JSON.stringify(state));}catch{}\n}\nfunction fillInputs(){for(const key of ['place','caption','lat','lon','date'])$('#'+key).value=state[key];render();}\nfunction readInputs(){\n for(const key of ['place','caption','date'])state[key]=$('#'+key).value;\n for(const key of ['lat','lon']){const n=Number($('#'+key).value);state[key]=Number.isFinite(n)?n:0;}\n requestId=crypto.randomUUID();$('#approve').checked=false;render();\n}\nasync function api(path,options){const r=await fetch(path,options);const data=await r.json();if(!r.ok)throw new Error(data.error||'Something went wrong.');return data;}\nfunction printCanvas(){return drawDesign(document.createElement('canvas'),state,4677,5881);}\nconst crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=(n>>>1)^((n&1)?0xedb88320:0);return n>>>0;});\nfunction crc32(bytes){let crc=0xffffffff;for(let i=0;i<bytes.length;i++)crc=(crc>>>8)^crcTable[(crc^bytes[i])&255];return (crc^0xffffffff)>>>0;}\nasync function canvasBlob(canvas){\n const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Could not create your print file. Please try another browser.')),'image/png'));\n const bytes=new Uint8Array(await blob.arrayBuffer()),v=new DataView(bytes.buffer);let offset=8;const chunks=[bytes.slice(0,8)];\n while(offset<bytes.length){const n=v.getUint32(offset),type=String.fromCharCode(...bytes.slice(offset+4,offset+8));if(type!=='pHYs')chunks.push(bytes.slice(offset,offset+12+n));if(type==='IHDR'){\n  const phys=new Uint8Array(21),pv=new DataView(phys.buffer);pv.setUint32(0,9);phys.set([112,72,89,115],4);pv.setUint32(8,11811);pv.setUint32(12,11811);phys[16]=1;pv.setUint32(17,crc32(phys.slice(4,17)));chunks.push(phys);\n }offset+=12+n;}\n return new Blob(chunks,{type:'image/png'});\n}\nasync function base64(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Could not read your print file.'));reader.readAsDataURL(blob);});}\nasync function download(){\n const button=$('#download');for(const key of ['place','lat','lon','date','caption'])if(!$('#'+key).reportValidity())return;\n button.disabled=true;const before=button.textContent;button.textContent='Rendering your print…';\n try{const canvas=printCanvas(),blob=await canvasBlob(canvas),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='somewhere-yours-'+state.place.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);canvas.width=canvas.height=1;}catch(e){$('#checkout-error').textContent=e.message;}finally{button.disabled=false;button.textContent=before;}\n}\nasync function checkout(event){\n event.preventDefault();const button=$('#checkout-button'),error=$('#checkout-error');error.textContent='';\n if(!configuration?.checkoutReady){error.textContent='Checkout is awaiting the store’s Stripe connection. Your design can still be downloaded.';return;}\n if(!$('#design-form').reportValidity())return;\n button.disabled=true;button.firstElementChild.textContent='Preparing your custom print…';\n try{\n  const canvas=printCanvas(),blob=await canvasBlob(canvas),png=await base64(blob);canvas.width=canvas.height=1;\n  const result=await api('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({design:{...state},png,requestId})});\n  try{localStorage.setItem('somewhere-yours-last-order',JSON.stringify({id:result.orderId,token:result.orderToken}));}catch{}\n  window.location.assign(result.url);\n }catch(e){error.textContent=e.message;button.disabled=false;button.firstElementChild.textContent='Continue to checkout';}\n}\nfunction setupDialogs(){\n for(const button of $$('[data-dialog]'))button.addEventListener('click',()=>$('#'+button.dataset.dialog).showModal());\n for(const dialog of $$('dialog')){dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();});}\n}\nlet refreshing=false;\nasync function refreshOrder(){\n if(refreshing)return;refreshing=true;$('#refresh-order').disabled=true;$('#order-error').textContent='';\n const id=location.pathname.split('/')[2],token=new URLSearchParams(location.search).get('token'),base='/api/orders/'+id+'?token='+encodeURIComponent(token||'');\n try{\n  let order=await api(base);\n  if(['pending_payment','paid_fulfillment_error','submitting'].includes(order.status)){\n   try{await api('/api/orders/'+id+'/reconcile?token='+encodeURIComponent(token||''),{method:'POST'});}catch(e){$('#order-error').textContent=e.message;}\n   order=await api(base);\n  }\n  const submitted=['sandbox_submitted','submitted'].includes(order.status);\n  $('#order-title').textContent=submitted?'Your somewhere is on its way.':order.status==='paid_fulfillment_error'?'Payment received. Print pending.':'Your order is saved.';\n  $('#order-message').textContent=order.status==='sandbox_submitted'?'Your test payment succeeded and the order was accepted by Prodigi’s sandbox. No money was charged, and no shirt will be shipped.':order.status==='submitted'?'Payment confirmed. Your approved print has been sent to Prodigi for production.':order.status==='submitting'?'Payment confirmed. We’re submitting your artwork to the print provider. Refresh in a moment.':order.status==='paid_fulfillment_error'?'Your payment is recorded. The print service needs a retry; use Refresh order status.':'Payment has not yet been confirmed. Nothing has been sent to print.';\n  const card=$('#order-card');card.replaceChildren();\n  const badge=document.createElement('span');badge.className='order-status';badge.textContent=order.status.replaceAll('_',' ');card.append(badge);\n  const values=[['Your design',order.design.place+' · '+order.design.color+' · '+order.design.size.toUpperCase()],['Coordinates',coords(order.design)],['Your story',order.design.caption],['Date',order.design.date],['Order reference',order.id],['Print reference',order.prodigiId||'Awaiting payment-confirmed submission']];\n  for(const [label,value] of values){const p=document.createElement('p'),strong=document.createElement('strong');strong.textContent=label+': ';p.append(strong,document.createTextNode(value));if(label.includes('reference'))p.className='order-ref';card.append(p);}\n  if(order.shipment?.trackingNumber){const p=document.createElement('p');p.textContent='Tracking: '+order.shipment.trackingNumber;card.append(p);}\n  if(order.status==='submitting')setTimeout(refreshOrder,10000);\n }catch(e){$('#order-title').textContent='We couldn’t find that order.';$('#order-message').textContent='Use the complete order link including its private access token.';$('#order-error').textContent=e.message;}\n finally{refreshing=false;$('#refresh-order').disabled=false;}\n}\nasync function init(){\n setupDialogs();\n shirt($('#hero-shirt'),presets['big-sur']);Object.values(presets).forEach((d,i)=>shirt($('#example-'+i),d));\n try{const saved=JSON.parse(localStorage.getItem('somewhere-yours-design'));if(saved&&['black','natural','white'].includes(saved.color)&&palettes[saved.palette])state={...state,...saved};}catch{}\n fillInputs();\n for(const input of $$('#design-form input:not([type=checkbox])'))input.addEventListener('input',readInputs);\n for(const key of ['palette','color','size'])for(const button of $$('[data-'+key+']'))button.addEventListener('click',()=>{state[key]=button.dataset[key];requestId=crypto.randomUUID();$('#approve').checked=false;render();});\n for(const button of $$('[data-preset]'))button.addEventListener('click',()=>{state={...presets[button.dataset.preset]};requestId=crypto.randomUUID();$('#approve').checked=false;fillInputs();$('#studio').scrollIntoView({behavior:'smooth'});});\n $('#download').addEventListener('click',download);$('#design-form').addEventListener('submit',checkout);$('#refresh-order').addEventListener('click',refreshOrder);\n try{\n  configuration=await api('/api/config');\n  if(configuration.checkoutReady){$('#payment-notice').textContent=configuration.sandbox?'Test checkout is ready. Use Stripe test card 4242 4242 4242 4242, any future expiry and any CVC. No real charge or shipment.':'Checkout is ready. Taxes, if applicable, appear in Stripe Checkout.';}\n  else{$('#payment-notice').textContent='Sandbox preview · Checkout awaits the merchant’s Stripe connection. Customize your shirt and download the print now.';}\n  if(!configuration.sandbox)$('#testbar').textContent='MADE FOR YOUR SOMEWHERE · Original personal prints, made to order.';\n }catch{$('#payment-notice').textContent='Checkout connection unavailable. Your personal print can still be downloaded.';}\n if(location.pathname.startsWith('/order/')){$('#storefront').classList.add('hidden');$('#order-view').classList.remove('hidden');await refreshOrder();}\n else if(new URLSearchParams(location.search).get('checkout')==='cancelled'){$('#checkout-error').textContent='Checkout was canceled. No shirt has been sent to print. Your design is still here.';requestId=crypto.randomUUID();}\n}\ninit();\n";
const SKU = 'GLOBAL-TEE-GIL-64000';
const PRICE = 3600, SHIPPING = 500, TOTAL = PRICE + SHIPPING;
const WIDTH = 4677, HEIGHT = 5881;
const MAX_BODY = 12 * 1024 * 1024;
class HttpError extends Error { constructor(status,message){super(message);this.status=status;} }
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
const now=()=>Math.floor(Date.now()/1000);
